let attempt = 0;
function connect() {
  const ws = new WebSocket(URL);
  ws.onopen = () => { attempt = 0; /* 성공하면 리셋 */ resume(ws); };
  ws.onclose = () => {
    const base = 1000, cap = 30000;
    const delay = Math.min(cap, base * 2 ** attempt);   // 지수 백오프
    const wait = delay / 2 + Math.random() * (delay / 2); // 흔들기(jitter)
    attempt++;
    setTimeout(connect, wait);                          // 예의 있게 재시도
  };
}
// 흔들기 없으면 → 서버 재시작 시 모든 클라가 같은 초에 몰려 다시 죽음

// 서버: 모든 변경에 증가하는 번호(시퀀스)를 붙인다
// 클라: 마지막으로 받은 번호를 기억
let lastSeq = 5;
ws.onopen = () => ws.send({ type: 'resume', since: lastSeq });

// 서버: since 이후의 변경만 보낸다(전체 재전송 X, 증분)
ws.onmessage = (msg) => {
  applyChange(msg);
  lastSeq = msg.seq;   // 받을 때마다 갱신
};
// 서버에 그 번호 이후가 없으면(너무 뒤처짐) → 전체 스냅샷으로 폴백
